// #Hard #Array #Dynamic_Programming #2022_03_28_Time_80_ms_(43.42%)_Space_42.9_MB_(71.71%)
public class Solution {
    private static final int MOD = 1000000007;

    public int profitableSchemes(int n, int minProfit, int[] group, int[] profit) {
        int m = group.length;
        int[][][] dp = new int[m + 1][n + 1][minProfit + 1];

        dp[0][0][0] = 1;

        for (int i = 1; i <= m; i++) {
            for (int g = 0; g <= n; g++) {
                for (int p = 0; p <= minProfit; p++) {
                    dp[i][g][p] = (dp[i][g][p] + dp[i - 1][g][p]) % MOD;
                    if (g >= group[i - 1]) {
                        int newProfit = Math.min(minProfit, p + profit[i - 1]);
                        dp[i][g][newProfit] = (dp[i][g][newProfit] + dp[i - 1][g - group[i - 1]][p]) % MOD;
                    }
                }
            }
        }

        int result = 0;
        for (int g = 0; g <= n; g++) {
            for (int p = minProfit; p <= minProfit; p++) {
                result = (result + dp[m][g][p]) % MOD;
            }
        }

        return result;
    }
}

