// #Medium #String #2022_03_24_Time_1_ms_(84.30%)_Space_42.1_MB_(63.64%)
public class Solution {
    public String maskPII(String s) {
        if (s.contains("@")) {
            return maskEmail(s);
        } else {
            return maskPhoneNumber(s);
        }
    }

    private String maskEmail(String email) {
        String[] parts = email.split("@");
        String name = parts[0];
        String domain = parts[1];

        String lowerName = name.toLowerCase();
        StringBuilder maskedName = new StringBuilder();
        maskedName.append(lowerName.charAt(0));
        if (lowerName.length() > 2) {
            for (int i = 1; i < lowerName.length() - 1; i++) {
                maskedName.append("*");
            }
        }
        maskedName.append(lowerName.charAt(lowerName.length() - 1));

        String maskedDomain = domain.toLowerCase();

        return maskedName.toString() + "@" + maskedDomain;
    }

    private String maskPhoneNumber(String phoneNumber) {
        StringBuilder digits = new StringBuilder();
        for (char c : phoneNumber.toCharArray()) {
            if (Character.isDigit(c)) {
                digits.append(c);
            }
        }

        int countryCodeLength = 0;
        if (digits.length() == 10) {
            return "-" + digits.substring(0, 1) + "****" + digits.substring(5);
        } else if (digits.length() == 11 && digits.charAt(0) == '1') {
            return "+1-" + digits.substring(1, 2) + "****" + digits.substring(6);
        } else if (digits.length() == 12 && digits.charAt(0) == '1') {
            return "+1--" + digits.substring(2, 3) + "****" + digits.substring(7);
        } else if (digits.length() == 13 && digits.charAt(0) == '1') {
            return "+1---" + digits.substring(3, 7) + digits.substring(7);
        } else {
            return "+---" + digits.substring(digits.length() - 4);
        }
    }
}

