import java.util.Arrays;

public class Solution {
    public double soupServings(int n) {
        if (n >= 400) {
            return 1.0;
        }

        double[][] dp = new double[n + 1][n + 1];

        for (int i = 0; i <= n; i++) {
            Arrays.fill(dp[i], -1.0);
        }

        return solve(n, n, dp);
    }

    private double solve(int i, int j, double[][] dp) {
        if (i == 0 && j == 0) {
            return 0.0;
        }

        if (i == 0 && j > 0) {
            return 0.0;
        }

        if (j == 0 && i > 0) {
            return 1.0;
        }

        if (dp[i][j] != -1.0) {
            return dp[i][j];
        }

        double prob1 = 0.0;
        if (i >= 100) {
            prob1 = solve(i - 100, j, dp);
        } else {
            prob1 = solve(0, j, dp);
        }

        double prob2 = 0.0;
        if (i >= 75 && j >= 25) {
            prob2 = solve(i - 75, j - 25, dp);
        } else if (i >= 75) {
            prob2 = solve(0, j, dp);
        } else if (j >= 25) {
            prob2 = solve(i, 0, dp);
        } else {
            prob2 = 0.0;
        }

        double prob3 = 0.0;
        if (i >= 50 && j >= 50) {
            prob3 = solve(i - 50, j - 50, dp);
        } else if (i >= 50) {
            prob3 = solve(0, j, dp);
        } else if (j >= 50) {
            prob3 = solve(i, 0, dp);
        } else {
            prob3 = 0.0;
        }

        double prob4 = 0.0;
        if (i >= 25 && j >= 75) {
            prob4 = solve(i - 25, j - 75, dp);
        } else if (i >= 25) {
            prob4 = solve(0, j, dp);
        } else if (j >= 75) {
            prob4 = solve(i, 0, dp);
        } else {
            prob4 = 0.0;
        }

        double result = 0.25 * (prob1 + prob2 + prob3 + prob4);
        dp[i][j] = result;
        return result;
    }
}

