public class Solution {
    public int[][] spiralMatrixIII(int rows, int cols, int y, int x) {
        int[][] result = new int[rows * cols][2];
        int index = 0;
        result[index][0] = y;
        result[index][1] = x;
        index++;

        int step = 1;
        while (index < rows * cols) {
            // Move right
            for (int i = 0; i < step; i++) {
                x++;
                if (y >= 0 && y < rows && x >= 0 && x < cols) {
                    result[index][0] = y;
                    result[index][1] = x;
                    index++;
                    if (index == rows * cols) break;
                }
            }
            if (index == rows * cols) break;

            // Move down
            for (int i = 0; i < step; i++) {
                y++;
                if (y >= 0 && y < rows && x >= 0 && x < cols) {
                    result[index][0] = y;
                    result[index][1] = x;
                    index++;
                    if (index == rows * cols) break;
                }
            }
            if (index == rows * cols) break;

            step++;

            // Move left
            for (int i = 0; i < step; i++) {
                x--;
                if (y >= 0 && y < rows && x >= 0 && x < cols) {
                    result[index][0] = y;
                    result[index][1] = x;
                    index++;
                    if (index == rows * cols) break;
                }
            }
            if (index == rows * cols) break;

            // Move up
            for (int i = 0; i < step; i++) {
                y--;
                if (y >= 0 && y < rows && x >= 0 && x < cols) {
                    result[index][0] = y;
                    result[index][1] = x;
                    index++;
                    if (index == rows * cols) break;
                }
            }
            if (index == rows * cols) break;

            step++;
        }

        return result;
    }
}

