    public TreeNode smallestSubtreeWithAllDeepestNodes(TreeNode root) {
        int[] maxDepth = {0};
        return smallestSubtreeWithAllDeepestNodesHelper(root, maxDepth);
    }

    private TreeNode smallestSubtreeWithAllDeepestNodesHelper(TreeNode node, int[] maxDepth) {
        if (node == null) {
            return null;
        }

        TreeNode left = smallestSubtreeWithAllDeepestNodesHelper(node.left, maxDepth);
        TreeNode right = smallestSubtreeWithAllDeepestNodesHelper(node.right, maxDepth);

        int depth = Math.max(getHeight(left), getHeight(right)) + 1;
        if (depth > maxDepth[0]) {
            maxDepth[0] = depth;
            return node;
        } else if (depth == maxDepth[0]) {
            return node;
        } else {
            return null;
        }
    }

    private int getHeight(TreeNode node) {
        if (node == null) {
            return 0;
        }
        return 1 + Math.max(getHeight(node.left), getHeight(node.right));
    }
}

