import java.util.LinkedList;
import java.util.Queue;

public class Solution {
    public int kSimilarity(String s1, String s2) {
        if (s1.equals(s2)) {
            return 0;
        }

        int n = s1.length();
        Queue<String> queue = new LinkedList<>();
        queue.offer(s1);
        int steps = 0;
        boolean[] visited = new boolean[1 << n];
        visited[0] = true;

        while (!queue.isEmpty()) {
            int size = queue.size();
            for (int i = 0; i < size; i++) {
                String curr = queue.poll();
                if (curr.equals(s2)) {
                    return steps;
                }

                int j = 0;
                while (j < n && curr.charAt(j) == s2.charAt(j)) {
                    j++;
                }

                for (int k = j + 1; k < n; k++) {
                    if (curr.charAt(k) == s2.charAt(j)) {
                        String next = swap(curr, j, k);
                        int mask = 0;
                        for (int l = 0; l < n; l++) {
                            if (next.charAt(l) != s2.charAt(l)) {
                                mask |= (1 << l);
                            }
                        }

                        if (!visited[mask]) {

                            queue.offer(next);
                            visited[mask] = true;
                        }
                    }
                }
            }
            steps++;
        }

        return -1;
    }

    private String swap(String s, int i, int j) {
        char[] chars = s.toCharArray();
        char temp = chars[i];
        chars[i] = chars[j];
        chars[j] = temp;
        return new String(chars);
    }
}

