import java.util.Arrays;

public class Solution {
    public int minSwap(int[] nums1, int[] nums2) {
        int n = nums1.length;
        int[][] dp = new int[n][2];

        for (int i = 0; i < n; i++) {
            Arrays.fill(dp[i], Integer.MAX_VALUE);
        }

        dp[0][0] = 0;
        dp[0][1] = 1;

        for (int i = 1; i < n; i++) {
            // Case 1: Don't swap
            if (nums1[i] > nums1[i - 1] && nums2[i] > nums2[i - 1]) {
                dp[i][0] = Math.min(dp[i][0], dp[i - 1][0]);
                dp[i][1] = Math.min(dp[i][1], dp[i - 1][1]);
            }

            // Case 2: Swap
            if (nums1[i] > nums2[i - 1] && nums2[i] > nums1[i - 1]) {
                dp[i][0] = Math.min(dp[i][0], dp[i - 1][1]);
                dp[i][1] = Math.min(dp[i][1], dp[i - 1][0]);
            }

            // Consider swapping even if the above conditions are not met
            if (nums1[i] <= nums1[i - 1] && nums2[i] > nums1[i - 1]) {
                dp[i][0] = Math.min(dp[i][0], dp[i - 1][1]);
            }
            if (nums2[i] <= nums2[i - 1] && nums1[i] > nums2[i - 1]) {
                dp[i][1] = Math.min(dp[i][1], dp[i - 1][0]);
            }

            if (nums1[i] > nums1[i-1] && nums2[i] <= nums2[i-1]) {
                dp[i][0] = Math.min(dp[i][0], dp[i-1][0]);
            }
            if (nums2[i] > nums2[i-1] && nums1[i] <= nums1[i-1]) {
                dp[i][1] = Math.min(dp[i][1], dp[i-1][1]);
            }

            dp[i][0] = Math.min(dp[i][0], dp[i-1][0] + 1);
            dp[i][1] = Math.min(dp[i][1], dp[i-1][1] + 1);
        }

        return Math.min(dp[n - 1][0], dp[n - 1][1]);
    }
}

