import java.util.Arrays;

public class Solution {
    public int matrixScore(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;
        int maxScore = 0;

        // Iterate through all possible row flip combinations
        for (int i = 0; i < (1 << m); i++) {
            int[][] tempGrid = Arrays.stream(grid).map(int[]::clone).toArray(int[][]::new);

            // Apply row flips based on the current combination
            for (int j = 0; j < m; j++) {
                if ((i & (1 << j)) != 0) {
                    for (int k = 0; k < n; k++) {
                        tempGrid[j][k] = 1 - tempGrid[j][k];
                    }
                }
            }

            // Calculate the score for the current grid
            int currentScore = 0;
            for (int j = 0; j < n; j++) {
                int ones = 0;
                for (int k = 0; k < m; k++) {
                    if (tempGrid[k][j] == 1) {
                        ones++;
                    }
                }
                currentScore += Math.max(ones, m - ones) * (1 << (n - 1 - j));
            }

            maxScore = Math.max(maxScore, currentScore);
        }

        return maxScore;
    }
}

