import java.util.PriorityQueue;

public class Solution {
    public int[] advantageCount(int[] nums1, int[] nums2) {
        if (nums1 == null || nums2 == null || nums1.length == 0 || nums2.length == 0) {
            return new int[0];
        }

        int n = nums1.length;
        Integer[] nums1Indices = new Integer[n];
        for (int i = 0; i < n; i++) {
            nums1Indices[i] = i;
        }

        Arrays.sort(nums1Indices, Comparator.comparingInt(i -> nums1[i]));

        Integer[] nums2Indices = new Integer[n];
        for (int i = 0; i < n; i++) {
            nums2Indices[i] = i;
        }

        Arrays.sort(nums2Indices, Comparator.comparingInt(i -> nums2[i]));

        int[] result = new int[n];
        PriorityQueue<Integer> pq = new PriorityQueue<>((a, b) -> nums1[a] - nums1[b]);

        for (int i = 0; i < n; i++) {
            pq.offer(nums1Indices[i]);
        }

        for (int i = n - 1; i >= 0; i--) {
            int index = nums2Indices[i];
            int bestIndex = -1;
            for (Integer j : pq) {
                if (nums1[j] > nums2[index]) {
                    bestIndex = j;
                    break;
                }
            }

            if (bestIndex != -1) {
                result[index] = nums1[bestIndex];
                pq.remove(bestIndex);
            } else {
                result[index] = nums1[pq.poll()];
            }
        }

        return result;
    }
}

