public class Solution {
    public int numberOfWays(int startPos, int endPos, int k) {
        int diff = Math.abs(startPos - endPos);
        if (diff > k) {
            return 0;
        }

        long[][] dp = new long[k + 1][k + 1];
        int MOD = 1000000007;

        // Initialize base case: dp[0][startPos] = 1
        dp[0][startPos] = 1;

        for (int i = 1; i <= k; i++) {
            for (int j = 0; j <= k; j++) {
                // Check if we can move left from the previous position
                if (j - 1 >= 0) {
                    dp[i][j] = (dp[i][j] + dp[i - 1][j - 1]) % MOD;
                }
                // Check if we can move right from the previous position
                if (j + 1 <= k) {
                    dp[i][j] = (dp[i][j] + dp[i - 1][j + 1]) % MOD;
                }
            }
        }

        return (int) dp[k][endPos];
    }
}

