import java.util.HashSet;
import java.util.Set;
public class Solution {
    public long countExcellentPairs(int[] nums, int k) {
        Set<Integer> distinctNums = new HashSet<>();
        for (int num : nums) {
            distinctNums.add(num);
        }

        int[] setBitsCount = new int[distinctNums.size()];
        int index = 0;
        for (int num : distinctNums) {
            int count = 0;
            int temp = num;
            while (temp > 0) {
                count += (temp & 1);
                temp >>= 1;
            }
            setBitsCount[index++] = count;
        }

        long count = 0;
        int[] numArr = distinctNums.stream().mapToInt(Integer::intValue).toArray();

        for (int i = 0; i < numArr.length; i++) {
            for (int j = 0; j < numArr.length; j++) {
                int orResult = numArr[i] | numArr[j];
                int andResult = numArr[i] & numArr[j];

                int orSetBits = 0;
                int tempOr = orResult;
                while (tempOr > 0) {
                    orSetBits += (tempOr & 1);
                    tempOr >>= 1;
                }

                int andSetBits = 0;
                int tempAnd = andResult;
                while (tempAnd > 0) {
                    andSetBits += (tempAnd & 1);
                    tempAnd >>= 1;
                }

                if (orSetBits + andSetBits >= k) {
                    count++;
                }
            }
        }

        return count;
    }
}

