import com.github.leetcode.TreeNode;
import java.util.*;

public class Solution {
    public int amountOfTime(TreeNode root, int start) {
        // Build the graph
        Map<TreeNode, List<TreeNode>> graph = new HashMap<>();
        buildGraph(root, graph);

        // Find the starting node
        TreeNode startNode = findNode(root, start);

        // Perform BFS
        Queue<TreeNode> queue = new LinkedList<>();
        queue.offer(startNode);
        Set<TreeNode> visited = new HashSet<>();
        visited.add(startNode);
        int minutes = 0;

        while (!queue.isEmpty()) {
            int size = queue.size();
            for (int i = 0; i < size; i++) {
                TreeNode node = queue.poll();
                if (graph.containsKey(node)) {
                    for (TreeNode neighbor : graph.get(node)) {
                        if (!visited.contains(neighbor)) {
                            visited.add(neighbor);
                            queue.offer(neighbor);
                        }
                    }
                }
            }
            minutes++;
        }

        return minutes - 1;
    }

    private void buildGraph(TreeNode root, Map<TreeNode, List<TreeNode>> graph) {
        if (root == null) {
            return;
        }

        if (!graph.containsKey(root)) {
            graph.put(root, new ArrayList<>());
        }

        if (root.left != null) {
            if (!graph.containsKey(root.left)) {
                graph.put(root.left, new ArrayList<>());
            }
            graph.get(root).add(root.left);
            graph.get(root.left).add(root);
        }

        if (root.right != null) {
            if (!graph.containsKey(root.right)) {
                graph.put(root.right, new ArrayList<>());
            }
            graph.get(root).add(root.right);
            graph.get(root.right).add(root);
        }

        buildGraph(root.left, graph);
        buildGraph(root.right, graph);
    }

    private TreeNode findNode(TreeNode root, int start) {
        if (root == null) {
            return null;
        }

        if (root.val == start) {
            return root;
        }

        TreeNode left = findNode(root.left, start);
        if (left != null) {
            return left;
        }

        return findNode(root.right, start);
    }
}

