import java.util.HashMap;
import java.util.ArrayList;
import java.util.List;

public class Solution {
    public long countPairs(int n, int[][] edges) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            adj.add(new ArrayList<>());
        }
        for (int[] edge : edges) {
            int u = edge[0];
            int v = edge[1];
            adj.get(u).add(v);
            adj.get(v).add(u);
        }

        boolean[] visited = new boolean[n];
        List<Integer> components = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            if (!visited[i]) {
                int count = dfs(i, adj, visited);
                components.add(count);
            }
        }

        long totalPairs = (long) n * (n - 1) / 2;
        long reachablePairs = 0;
        for (int componentSize : components) {
            reachablePairs += (long) componentSize * (componentSize - 1) / 2;
        }

        return totalPairs - reachablePairs;
    }

    private int dfs(int node, List<List<Integer>> adj, boolean[] visited) {
        visited[node] = true;
        int count = 1;
        for (int neighbor : adj.get(node)) {
            if (!visited[neighbor]) {
                count += dfs(neighbor, adj, visited);
            }
        }
        return count;
    }
}

