import java.util.PriorityQueue;
import java.util.HashSet;
import java.util.Set;

public class Solution {
    public int maximumRobots(int[] chargeTimes, int[] runningCosts, long budget) {
        int n = chargeTimes.length;
        int left = 0;
        long currentSum = 0;
        int maxRobots = 0;
        PriorityQueue<Integer> maxHeap = new PriorityQueue<>((a, b) -> b - a);
        Set<Integer> removed = new HashSet<>();

        for (int right = 0; right < n; right++) {
            currentSum += runningCosts[right];
            maxHeap.offer(chargeTimes[right]);

            while (!maxHeap.isEmpty() && currentSum + (long)maxHeap.peek() > budget) {
                currentSum -= runningCosts[left];
                removed.add(chargeTimes[left]);
                left++;

                while (!maxHeap.isEmpty() && removed.contains(maxHeap.peek())) {
                    maxHeap.poll();
                }
            }

            maxRobots = Math.max(maxRobots, right - left + 1);
        }

        return maxRobots;
    }
}

