import java.util.HashMap;
import java.util.Map;

public class Solution {
    public boolean matchReplacement(String s, String sub, char[][] mappings) {
        if (sub.isEmpty()) {
            return true;
        }

        int n = s.length();
        int m = sub.length();

        if (m > n) {
            return false;
        }

        Map<Character, Character> mappingMap = new HashMap<>();
        for (char[] mapping : mappings) {
            mappingMap.put(mapping[0], mapping[1]);
        }

        for (int i = 0; i <= n - m; i++) {
            if (canMatch(s.substring(i, i + m), sub, mappingMap)) {
                return true;
            }
        }

        return false;
    }

    private boolean canMatch(String s, String sub, Map<Character, Character> mappingMap) {
        // If the lengths of s and sub are different, they cannot match.
        if (s.length() != sub.length()) {
            return false;
        }

        for (int i = 0; i < s.length(); i++) {
            char sChar = s.charAt(i);
            char subChar = sub.charAt(i);

            if (sChar != subChar) {
                if (!mappingMap.containsKey(subChar)) {
                    return false;
                }

                char replacementChar = mappingMap.get(subChar);
                if (replacementChar != sChar) {
                    return false;
                }
            }
        }

        return true;
    }
}

