public class Solution {
    public long minimumReplacement(int[] nums) {
        long operations = 0;
        int n = nums.length;
        int last = nums[n - 1];
        for (int i = n - 2; i >= 0; i--) {
            if (nums[i] > last) {
                int parts = (nums[i] + last - 1) / last;
                operations += parts - 1;
                last = nums[i] / parts;
            } else {
                last = nums[i];
            }
        }
        return operations;
    }
}

