public class Solution {
    public int minNumberOfHours(int initialEnergy, int initialExperience, int[] energy, int[] experience) {
        int hours = 0;
        int currentEnergy = initialEnergy;
        int currentExperience = initialExperience;

        for (int i = 0; i < energy.length; i++) {
            if (currentExperience > experience[i] && currentEnergy > energy[i]) {
                currentEnergy -= energy[i];
                currentExperience += experience[i];
            } else {
                int expDiff = Math.max(0, experience[i] - currentExperience + 1);
                int energyDiff = Math.max(0, energy[i] - currentEnergy + 1);

                hours += expDiff + energyDiff;
                currentExperience += expDiff;
                currentEnergy += energyDiff;

                if (currentExperience > experience[i] && currentEnergy > energy[i]) {
                    currentEnergy -= energy[i];
                    currentExperience += experience[i];
                }
            }
        }

        return hours;
    }
