import java.util.*;
import java.lang.*;

class Solution {
    public int garbageCollection(String[] garbage, int[] travel) {
        int m = 0, p = 0, g = 0;
        int lastM = -1, lastP = -1, lastG = -1;
        int totalTime = 0;

        for (int i = 0; i < garbage.length; i++) {
            String houseGarbage = garbage[i];
            for (char c : houseGarbage.toCharArray()) {
                if (c == 'M') {
                    m++;
                } else if (c == 'P') {
                    p++;
                } else {
                    g++;
                }
            }
        }

        if (m == 0 && p == 0 && g == 0) {
            return 0;
        }

        int firstM = -1, firstP = -1, firstG = -1;

        if (m > 0) {
            for (int i = 0; i < garbage.length; i++) {
                if (garbage[i].contains("M")) {
                    if (firstM == -1) {
                        firstM = i;
                        totalTime += travel[i];
                        lastM = i;
                    } else {
                        totalTime += travel[i - lastM];
                        lastM = i;
                    }
                }
            }
        }

        if (p > 0) {
            for (int i = 0; i < garbage.length; i++) {
                if (garbage[i].contains("P")) {
                    if (firstP == -1) {
                        firstP = i;
                        totalTime += travel[i];
                        lastP = i;
                    } else {
                        totalTime += travel[i - lastP];
                        lastP = i;
                    }
                }
            }
        }

        if (g > 0) {
            for (int i = 0; i < garbage.length; i++) {
                if (garbage[i].contains("G")) {
                    if (firstG == -1) {
                        firstG = i;
                        totalTime += travel[i];
                        lastG = i;
                    } else {
                        totalTime += travel[i - lastG];
                        lastG = i;
                    }
                }
            }
        }

        return totalTime;
    }
