public class Solution {

    public int[] maximumSegmentSum(int[] nums, int[] removeQueries) {
        int n = nums.length;
        int[] answer = new int[n];
        boolean[] removed = new boolean[n];

        for (int i = 0; i < n; i++) {
            int removeIndex = removeQueries[i];
            removed[removeIndex] = true;

            int left = -1;
            int right = -1;

            // Find left boundary
            for (int j = removeIndex - 1; j >= 0; j--) {
                if (removed[j]) {
                    left = j;
                    break;
                }
            }

            // Find right boundary
            for (int j = removeIndex + 1; j < n; j++) {
                if (removed[j]) {
                    right = j;
                    break;
                }
            }

            if (left == -1) {
                left = -1;
            } else {
                left++;
            }

            if (right == -1) {
                right = n;
            }

            long maxSum = 0;
            long currentSum = 0;

            for (int j = left + 1; j < right; j++) {
                if (!removed[j]) {
                    currentSum += nums[j];
                    maxSum = Math.max(maxSum, currentSum);
                    if (currentSum < 0) {
                        currentSum = 0;
                    }
                } else {
                    currentSum = 0;
                }
            }

            answer[i] = (int)maxSum;
        }

        return answer;
    }
