        Set<Character> upper = new HashSet<>();

        for (char c : s.toCharArray()) {
            if (Character.isLowerCase(c)) {
                lower.add(c);
            } else if (Character.isUpperCase(c)) {
                upper.add(c);
            }
        }

        Character greatest = null;
        for (char c = 'a'; c <= 'z'; c++) {
            if (lower.contains(c) && upper.contains(Character.toUpperCase(c))) {
                if (greatest == null || Character.toUpperCase(c) > greatest) {
                    greatest = Character.toUpperCase(c);
                }
            }
        }

        if (greatest == null) {
            return "";
        }

        return String.valueOf(greatest);
    }
}

