import java.util.Arrays;

public class Solution {
    public int longestCycle(int[] edges) {
        int n = edges.length;
        int[] visited = new int[n];
        Arrays.fill(visited, 0);
        int maxCycle = -1;

        for (int i = 0; i < n; i++) {
            if (visited[i] == 0) {
                int current = i;
                int count = 1;
                int[] path = new int[n];
                Arrays.fill(path, -1);
                path[current] = -1; // Mark the starting node's predecessor as -1

                while (current != -1 && visited[current] == 0) {
                    visited[current] = 1;
                    int next = edges[current];

                    if (next == -1) {
                        break;
                    }

                    if (visited[next] == 1) {
                        // Cycle detected
                        int cycleLength = 1;
                        int start = next;
                        int temp = current;

                        while (temp != start) {
                            cycleLength++;
                            temp = path[temp];
                        }

                        maxCycle = Math.max(maxCycle, cycleLength);
                        break;
                    }

                    if (path[next] == -1) {
                        path[next] = current;
                    }

                    current = next;
                }
            }
        }

        return maxCycle;
    }
}

