import java.util.PriorityQueue;

public class Solution {
    public long minSumSquareDiff(int[] nums1, int[] nums2, int k1, int k2) {
        int n = nums1.length;
        long[] diffs = new long[n];
        for (int i = 0; i < n; i++) {
            diffs[i] = Math.abs((long)nums1[i] - (long)nums2[i]);
        }

        PriorityQueue<Long> pq = new PriorityQueue<>((a, b) -> Long.compare(b, a));
        for (int i = 0; i < n; i++) {
            pq.offer(diffs[i]);
        }

        long k = (long)k1 + (long)k2;

        while (k > 0 && !pq.isEmpty()) {
            long top = pq.poll();
            if (top == 0) continue;

            long reduction = Math.min(k, top);
            k -= reduction;

            long newDiff = top - reduction;
            if (newDiff > 0) {
                pq.offer(newDiff);
            }
        }

        long result = 0;
        while (!pq.isEmpty()) {
            long item = pq.poll();
            result += item * item;
        }

        return result;
    }
}

