import java.util.Stack;

public class Solution {
    public String smallestNumber(String pattern) {
        int n = pattern.length();
        int[] ans = new int[n + 1];
        Stack<Integer> stack = new Stack<>();
        int num = 1;
        boolean[] used = new boolean[10];

        for (int i = 0; i < n; i++) {
            if (pattern.charAt(i) == 'I') {
                while (used[num]) {
                    num++;
                }
                stack.push(num++);
            } else {
                int top = stack.isEmpty() ? 10 : stack.peek();
                int nextNum = -1;
                for (int j = 1; j < top; j++) {
                    if (!used[j]) {
                        nextNum = j;
                        break;
                    }
                }
                if (nextNum == -1) {
                    nextNum = num++;
                }
                stack.push(nextNum);
                used[nextNum] = true;
            }
        }

        stack.push(num++);

        for (int i = n; i >= 0; i--) {
            ans[i] = stack.pop();
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i <= n; i++) {
            sb.append(ans[i]);
        }
        return sb.toString();
    }
}

