                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] > maxInRow) {
                        maxInRow = grid[i][j];
                        maxIndex = j;
                    }
                }
                maxDeleted = Math.max(maxDeleted, maxInRow);

                // Delete the element by shifting elements to the left
                for (int k = maxIndex; k < cols - 1; k++) {
                    grid[i][k] = grid[i][k + 1];
                }
            }
            answer += maxDeleted;
            cols--;
        }
        return answer;
    }
}

