public class Solution {
    public long makeSimilar(int[] nums, int[] target) {
        Map<Integer, Integer> numsFreq = new HashMap<>();
        Map<Integer, Integer> targetFreq = new HashMap<>();

        for (int num : nums) {
            numsFreq.put(num, numsFreq.getOrDefault(num, 0) + 1);
        }

        for (int num : target) {
            targetFreq.put(num, targetFreq.getOrDefault(num, 0) + 1);
        }

        long operations = 0;
        for (int num : numsFreq.keySet()) {
            int freqNums = numsFreq.get(num);
            int freqTarget = targetFreq.getOrDefault(num, 0);
            operations += Math.abs((long) freqNums - (long) freqTarget);
        }

        return operations / 2;
    }
}

