import java.util.PriorityQueue;

public class Solution {
    public long totalCost(int[] costs, int k, int candidates) {
        if (costs == null || costs.length == 0) {
            return 0;
        }

        int n = costs.length;
        if (k > n) {
            long totalCost = 0;
            for (int cost : costs) {
                totalCost += cost;
            }
            return totalCost;
        }

        PriorityQueue<int[]> left = new PriorityQueue<>((a, b) -> {
            if (a[0] != b[0]) {
                return a[0] - b[0];
            } else {
                return a[1] - b[1];
            }
        });
        PriorityQueue<int[]> right = new PriorityQueue<>((a, b) -> {
            if (a[0] != b[0]) {
                return a[0] - b[0];
            } else {
                return a[1] - b[1];
            }
        });

        for (int i = 0; i < Math.min(candidates, n); i++) {
            left.add(new int[]{costs[i], i});
        }

        for (int i = n - 1; i >= Math.max(n - 1 - candidates, 0); i--) {
            right.add(new int[]{costs[i], i});
        }

        long totalCost = 0;
        int leftIndex = candidates;
        int rightIndex = n - 1 - candidates;

        for (int i = 0; i < k; i++) {
            int[] leftMinArr = left.isEmpty() ? null : left.peek();
            int[] rightMinArr = right.isEmpty() ? null : right.peek();

            int leftMin = leftMinArr == null ? Integer.MAX_VALUE : leftMinArr[0];
            int rightMin = rightMinArr == null ? Integer.MAX_VALUE : rightMinArr[0];

            if (leftMin <= rightMin) {
                totalCost += leftMin;
                left.poll();
                if (leftIndex < n) {
                    left.add(new int[]{costs[leftIndex], leftIndex});
                    leftIndex++;
                }
            } else {
                totalCost += rightMin;
                right.poll();
                if (rightIndex >= 0) {
                    right.add(new int[]{costs[rightIndex], rightIndex});
                    rightIndex--;
                }
            }
        }

        return totalCost;
    }
}

