public class Solution {
    public int longestNiceSubarray(int[] nums) {
        int n = nums.length;
        int maxLength = 0;
        int currentLength = 0;
        int mask = 0;

        for (int i = 0; i < n; i++) {
            while ((mask & nums[i]) != 0) {
                mask ^= nums[i - currentLength];
                currentLength--;
            }
            mask |= nums[i];
            currentLength++;
            maxLength = Math.max(maxLength, currentLength);
        }

        return maxLength;
    }
}

