import java.util.Arrays;

public class Solution {
    private static final int MOD = 1000000007;

    public int numberOfPaths(int[][] grid, int k) {
        int m = grid.length;
        int n = grid[0].length;
        int[][][] dp = new int[m][n][k];
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                Arrays.fill(dp[i][j], -1);
            }
        }
        return solve(grid, 0, 0, k, dp, 0);
    }

    private int solve(int[][] grid, int row, int col, int k, int[][][] dp, int currentSum) {
        int m = grid.length;
        int n = grid[0].length;

        if (row == m - 1 && col == n - 1) {
            if ((currentSum + grid[row][col]) % k == 0) {
                return 1;
            } else {
                return 0;
            }
        }

        if (row >= m || col >= n) {
            return 0;
        }

        if (dp[row][col][currentSum % k] != -1) {
            return dp[row][col][currentSum % k];
        }

        long paths = 0;
        paths = (paths + solve(grid, row + 1, col, k, dp, (currentSum + grid[row][col]) % MOD)) % MOD;
        paths = (paths + solve(grid, row, col + 1, k, dp, (currentSum + grid[row][col]) % MOD)) % MOD;

        dp[row][col][currentSum % k] = (int) paths;
        return (int) paths;
    }
}

