import java.util.Arrays;

public class Solution {
    public int maxJump(int[] stones) {
        int n = stones.length;
        if (n <= 1) {
            return 0;
        }

        int minCost = Integer.MAX_VALUE;

        // Iterate through all permutations of visiting the stones
        int[] permutation = new int[n];
        boolean[] used = new boolean[n];
        minCost = generatePermutations(stones, 0, permutation, used, minCost);

        return minCost;
    }

    private int generatePermutations(int[] stones, int index, int[] permutation, boolean[] used, int minCost) {
        int n = stones.length;
        if (index == n) {
            // Calculate the cost of this permutation
            int currentCost = 0;
            for (int i = 0; i < n - 1; i++) {
                currentCost = Math.max(currentCost, Math.abs(stones[permutation[i]] - stones[permutation[i + 1]]));
            }
            currentCost = Math.max(currentCost, Math.abs(stones[permutation[n - 1]] - stones[permutation[0]]));
            return Math.min(minCost, currentCost);
        }

        for (int i = 0; i < n; i++) {
            if (!used[i]) {
                permutation[index] = i;
                used[i] = true;
                minCost = generatePermutations(stones, index + 1, permutation, used, minCost);
                used[i] = false;
            }
        }
        return minCost;
    }
}

