public class Solution {
    public List<Integer> goodIndices(int[] nums, int k) {
        int n = nums.length;
        List<Integer> goodIndices = new ArrayList<>();
        if (n < 2 * k) {
            return goodIndices;
        }
        for (int i = k; i < n - k; i++) {
            boolean isGood = true;
            // Check non-increasing order before index i
            for (int j = i - 1; j > i - k - 1; j--) {
                if (nums[j] < nums[j + 1]) {
                    isGood = false;
                    break;
                }
            }
            if (!isGood) continue;

            // Check non-decreasing order after index i
            for (int j = i + 1; j < i + k; j++) {
                if (nums[j] < nums[j - 1]) {
                    isGood = false;
                    break;
                }
            }

            if (isGood) {
                goodIndices.add(i);
            }
        }
        return goodIndices;
    }
}

