import java.util.ArrayList;
import java.util.List;

public class Solution {
    public int componentValue(int[] nums, int[][] edges) {
        int n = nums.length;
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            adj.add(new ArrayList<>());
        }
        for (int[] edge : edges) {
            int u = edge[0];
            int v = edge[1];
            adj.get(u).add(v);
            adj.get(v).add(u);
        }

        int totalSum = 0;
        for (int num : nums) {
            totalSum += num;
        }

        int maxDeletedEdges = -1;
        for (int i = 0; i < (1 << edges.length); i++) {
            List<int[]> remainingEdges = new ArrayList<>();
            int deletedEdges = 0;
            for (int j = 0; j < edges.length; j++) {
                if ((i & (1 << j)) == 0) {
                    remainingEdges.add(edges[j]);
                } else {
                    deletedEdges++;
                }
            }

            List<List<Integer>> components = getComponents(n, remainingEdges);

            if (components.isEmpty()) continue;

            boolean valid = true;
            int componentValue = -1;
            for (List<Integer> component : components) {
                int sum = 0;
                for (int node : component) {
                    sum += nums[node];
                }
                if (componentValue == -1) {
                    componentValue = sum;
                } else if (componentValue != sum) {
                    valid = false;
                    break;
                }
            }

            if (valid && totalSum % componentValue == 0 && totalSum / componentValue == components.size()) {
                maxDeletedEdges = Math.max(maxDeletedEdges, deletedEdges);
            }
        }

        return maxDeletedEdges;
    }

    private List<List<Integer>> getComponents(int n, List<int[]> edges) {
        List<List<Integer>> components = new ArrayList<>();
        boolean[] visited = new boolean[n];
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            adj.add(new ArrayList<>());
        }
        for (int[] edge : edges) {
            int u = edge[0];
            int v = edge[1];
            adj.get(u).add(v);
            adj.get(v).add(u);
        }

        for (int i = 0; i < n; i++) {
            if (!visited[i]) {
                List<Integer> component = new ArrayList<>();
                dfs(i, visited, adj, component);
                components.add(component);
            }
        }
        return components;
    }

    private void dfs(int node, boolean[] visited, List<List<Integer>> adj, List<Integer> component) {
        visited[node] = true;
        component.add(node);
        for (int neighbor : adj.get(node)) {
            if (!visited[neighbor]) {
                dfs(neighbor, visited, adj, component);
            }
        }
    }
}

