        if (n == 1) {
            return 0;
        }

        List<Pair> pairs = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            pairs.add(new Pair(nums[i], cost[i]));
        }

        pairs.sort(Comparator.comparingInt(p -> p.num));

        long totalCost = 0;
