            for (int j = i; j < n; j++) {
                if (customers.charAt(j) == 'Y') {
                    closedHoursPenalty++;
                }
            }

            int currentPenalty = openHoursPenalty + closedHoursPenalty;

            if (currentPenalty < minPenalty) {
                minPenalty = currentPenalty;
                bestClosingTime = i;
            }
        }

        return bestClosingTime;
    }
