class Solution {
    public int minimizeXor(int num1, int num2) {
        int setBits = Integer.bitCount(num2);
        int x = 0;

        if (num2 == 0) {
            return 0;
        }

        for (int i = 0; i < 32; i++) {
            if ((num2 & (1 << i)) != 0) {
                if ((x & (1 << i)) == 0) {
                    x |= (1 << i);
                    setBits--;
                }
            }
        }

        if (setBits > 0) {
            int j = 0;
            while ((x & (1 << j)) != 0) {
                j++;
            }
            x |= (1 << j);
        }

        int minXor = Integer.MAX_VALUE;
        int result = x;

        for (int i = 0; i < 32; i++) {
            int tempX = x;
            if ((tempX & (1 << i)) != 0) {
                tempX &= ~(1 << i);
                int count = Integer.bitCount(tempX);
                if (count == Integer.bitCount(num2)) {
                    if ((tempX ^ num1) < minXor) {
                        minXor = (tempX ^ num1);
                        result = tempX;
                    }
                }
            }
        }

        if ((x ^ num1) < minXor) {
            result = x;
        }

        return result;
    }
}

