public class Solution {
    public int[] secondGreaterElement(int[] nums) {
        int n = nums.length;
        int[] answer = new int[n];
        Stack<Integer> stack = new Stack<>();

        for (int i = n - 1; i >= 0; i--) {
            while (!stack.isEmpty() && stack.peek() <= nums[i]) {
                stack.pop();
            }

            if (stack.isEmpty()) {
                answer[i] = -1;
            } else {
                int firstGreater = stack.peek();
                stack.pop();

                if (stack.isEmpty()) {
                    answer[i] = -1;
                } else {
                    int secondGreater = stack.peek();
                    if (secondGreater > nums[i]) {
                        answer[i] = secondGreater;
                    } else {
                        answer[i] = -1;
                    }
                }
                stack.push(firstGreater);
            }
        }

        return answer;
    }
}

