import java.util.Arrays;
import java.util.PriorityQueue;

public class Solution {
    public int mostBooked(int n, int[][] meetings) {
        Arrays.sort(meetings, (a, b) -> a[0] - b[0]);

        PriorityQueue<Integer> availableRooms = new PriorityQueue<>();
        for (int i = 0; i < n; i++) {
            availableRooms.offer(i);
        }

        int[] roomCounts = new int[n];
        PriorityQueue<Meeting> delayedMeetings = new PriorityQueue<>((a, b) -> a.endTime - b.endTime);

        for (int[] meeting : meetings) {
            int startTime = meeting[0];
            int endTime = meeting[1];

            if (!availableRooms.isEmpty()) {
                int room = availableRooms.poll();
                roomCounts[room]++;
                delayedMeetings.offer(new Meeting(room, endTime));
            } else {
                if (!delayedMeetings.isEmpty()) {
                    Meeting earliestFinishedMeeting = delayedMeetings.peek();
                    if (earliestFinishedMeeting.endTime <= startTime) {
                        Meeting meetingToReuse = delayedMeetings.poll();
                        int room = meetingToReuse.room;
                        roomCounts[room]++;
                        delayedMeetings.offer(new Meeting(room, endTime));
                    } else {
                        delayedMeetings.offer(new Meeting(-1, endTime));
                    }
                } else {
                    delayedMeetings.offer(new Meeting(-1, endTime));
                }
            }
        }

        int maxMeetings = 0;
        int mostBookedRoom = 0;
        for (int i = 0; i < n; i++) {
            if (roomCounts[i] > maxMeetings) {
                maxMeetings = roomCounts[i];
                mostBookedRoom = i;
            } else if (roomCounts[i] == maxMeetings && i < mostBookedRoom) {
                mostBookedRoom = i;
            }
        }

        return mostBookedRoom;
    }

    static class Meeting {
        int room;
        int endTime;

        public Meeting(int room, int endTime) {
            this.room = room;
            this.endTime = endTime;
        }
    }
}

