public class Solution {
    public String[] splitMessage(String message, int limit) {
        if (limit <= 9) {
            return new String[0];
        }

        int n = message.length();
        int parts = (int) Math.ceil((double) n / (limit - 9));
        if (parts > 1000) {
            return new String[0];
        }

        String[] result = new String[parts];
        int start = 0;
        for (int i = 0; i < parts; i++) {
            int end = Math.min(start + limit - 9, n);

            if (start >= n) {
                return new String[0];
            }

            if (end <= start) {
                return new String[0];
            }

            String part = message.substring(start, end);
            result[i] = String.format("%d/%d", i + 1, parts) + part;
            start = end;
        }

        String reconstructed = "";
        for (String part : result) {
            reconstructed += part.substring(9);
        }

        if (!reconstructed.equals(message)) {
            return new String[0];
        }

        return result;
    }
}

