        ListNode prev = current;
        current = current.next;

        while (current != null) {
            if (current.val < maxVal) {
                prev.next = current.next;
            } else {
                maxVal = current.val;
                prev = current;
            }
            current = current.next;
        }

        return reverseList(reversedHead);
    }

    private ListNode reverseList(ListNode head) {
        ListNode prev = null;
        ListNode current = head;
        ListNode next = null;

        while (current != null) {
            next = current.next;
            current.next = prev;
            prev = current;
            current = next;
        }

        return prev;
    }
}

