import java.util.Arrays;

public class Solution {
    public int boxDelivering(int[][] boxes, int portsCount, int maxBoxes, int maxWeight) {
        int n = boxes.length;
        int[] dp = new int[n + 1];
        Arrays.fill(dp, Integer.MAX_VALUE);
        dp[0] = 0;

        for (int i = 1; i <= n; i++) {
            int boxesCount = 0;
            int weightSum = 0;
            int prevPort = -1;
            int trips = 0;

            for (int j = i - 1; j >= 0; j--) {
                boxesCount++;
                weightSum += boxes[j][1];

                if (boxesCount > maxBoxes || weightSum > maxWeight) {
                    break;
                }

                if (prevPort == -1) {
                    prevPort = boxes[j][0];
                } else if (boxes[j][0] != prevPort) {
                    trips++;
                    prevPort = boxes[j][0];
                }
            }

            if (dp[i - boxesCount] != Integer.MAX_VALUE) {
                dp[i] = Math.min(dp[i], dp[i - boxesCount] + 1 + trips);
            }
        }

        return dp[n];
    }
}

