public class Solution {
    public boolean canDistribute(int[] nums, int[] quantity) {
        Map<Integer, Integer> counts = new HashMap<>();
        for (int num : nums) {
            counts.put(num, counts.getOrDefault(num, 0) + 1);
        }

        int n = quantity.length;
        int[] used = new int[n];
        return solve(counts, quantity, used, 0);
    }

    private boolean solve(Map<Integer, Integer> counts, int[] quantity, int[] used, int customerIndex) {
        if (customerIndex == quantity.length) {
            return true;
        }

        for (Integer num : counts.keySet()) {
            if (counts.get(num) >= quantity[customerIndex]) {
                counts.put(num, counts.get(num) - quantity[customerIndex]);
                if (solve(counts, quantity, used, customerIndex + 1)) {
                    return true;
                }
                counts.put(num, counts.get(num) + quantity[customerIndex]);
            }
        }

        return false;
    }
}

