import java.util.Arrays;

public class Solution {
    public int minimumIncompatibility(int[] nums, int k) {
        int n = nums.length;
        if (n % k != 0) {
            return -1;
        }
        int subsetSize = n / k;
        Arrays.sort(nums);
        int[][] dp = new int[1 << n][k + 1];
        for (int i = 0; i < (1 << n); i++) {
            Arrays.fill(dp[i], Integer.MAX_VALUE);
        }
        dp[0][0] = 0;

        for (int mask = 0; mask < (1 << n); mask++) {
            for (int i = 0; i <= k; i++) {
                if (dp[mask][i] == Integer.MAX_VALUE) {
                    continue;
                }

                if (i == k) {
                    continue;
                }

                for (int j = 0; j < (1 << n); j++) {
                    if ((mask & j) != 0) {
                        continue;
                    }

                    int subsetSizeCount = 0;
                    int minVal = Integer.MAX_VALUE;
                    int maxVal = Integer.MIN_VALUE;
                    boolean valid = true;
                    for (int bit = 0; bit < n; bit++) {
                        if ((j & (1 << bit)) != 0) {
                            subsetSizeCount++;
                            minVal = Math.min(minVal, nums[bit]);
                            maxVal = Math.max(maxVal, nums[bit]);
                        }
                    }

                    if (subsetSizeCount != subsetSize) {
                        continue;
                    }

                    boolean hasDuplicates = false;
                    int[] subset = new int[subsetSize];
                    int subsetIndex = 0;
                    for (int bit = 0; bit < n; bit++) {
                        if ((j & (1 << bit)) != 0) {
                            for (int l = 0; l < subsetIndex; l++) {
                                if (subset[l] == nums[bit]) {
                                    hasDuplicates = true;
                                    break;
                                }
                            }
                            if (hasDuplicates) {
                                break;
                            }
                            subset[subsetIndex++] = nums[bit];
                        }
                    }

                    if (hasDuplicates) {
                        continue;
                    }

                    int incompatibility = maxVal - minVal;
                    dp[mask | j][i + 1] = Math.min(dp[mask | j][i + 1], dp[mask][i] + incompatibility);
                }
            }
        }

        int result = dp[(1 << n) - 1][k];
        return result == Integer.MAX_VALUE ? -1 : result;
    }
}

