public class Solution {
    public int createSortedArray(int[] instructions) {
        long cost = 0;
        int[] nums = new int[instructions.length];
        int n = instructions.length;
        for (int i = 0; i < n; i++) {
            int less = 0;
            int greater = 0;
            for (int j = 0; j < i; j++) {
                if (instructions[j] < instructions[i]) {
                    less++;
                } else if (instructions[j] > instructions[i]) {
                    greater++;
                }
            }
            cost = (cost + Math.min(less, greater)) % 1000000007;

            int insertPos = 0;
            while (insertPos < i && nums[insertPos] < instructions[i]) {
                insertPos++;
            }

            for (int j = i; j > insertPos; j--) {
                nums[j] = nums[j - 1];
            }
            nums[insertPos] = instructions[i];
        }
        return (int) cost;
    }
}

