public class Solution {
    /**
     * Given an integer array nums and an integer k. Find the maximum subarray sum of all the subarrays of nums that meet the following conditions:
     * The length of the subarray is k, and All the elements of the subarray are distinct.
     * Return the maximum subarray sum of all the subarrays that meet the conditions.
     * If no subarray meets the conditions, return 0.
     *
     * @param nums The input integer array.
     * @param k    The length of the subarray.
     * @return The maximum subarray sum of all the subarrays that meet the conditions.
     */
    public long maximumSubarraySum(int[] nums, int k) {
        if (nums == null || nums.length < k || k <= 0) {
            return 0;
        }

        long maxSum = 0;
        for (int i = 0; i <= nums.length - k; i++) {
            long currentSum = 0;
            Set<Integer> seen = new HashSet<>();
            boolean distinct = true;
            for (int j = i; j < i + k; j++) {
                if (!seen.add(nums[j])) {
                    distinct = false;
                    break;
                }
                currentSum += nums[j];
            }

            if (distinct) {
                maxSum = Math.max(maxSum, currentSum);
            }
        }

        return maxSum;
    }
}

