public class Solution {
    public String kthSmallestPath(int[] destination, int k) {
        int row = destination[0];
        int col = destination[1];
        StringBuilder sb = new StringBuilder();
        int totalMoves = row + col;
        int[][] dp = new int[row + 1][col + 1];

        dp[0][0] = 1;
        for (int i = 0; i <= row; i++) {
            for (int j = 0; j <= col; j++) {
                if (i > 0) {
                    dp[i][j] += dp[i - 1][j];
                }
                if (j > 0) {
                    dp[i][j] += dp[i][j - 1];
                }
            }
        }

        int current_row = 0;
        int current_col = 0;

        for (int i = 0; i < totalMoves; i++) {
            if (current_row < row) {
                int moves_down = 0;
                if (current_row + 1 <= row && current_col <= col) {
                    moves_down = dp[row - current_row - 1][col - current_col];
                }

                if (k <= moves_down) {
                    sb.append('V');
                    current_row++;
                } else {
                    sb.append('H');
                    current_col++;
                    k -= moves_down;
                }
            } else {
                sb.append('H');
                current_col++;
            }
        }

        return sb.toString();
