                for (TreeNode node : currentLevel) {
                    if (node.val % 2 == 0) {
                        return false;
                    }
                    if (node.val <= prevVal) {
                        return false;
                    }
                    prevVal = node.val;

                    if (node.left != null) {
                        nextLevel.add(node.left);
                    }
                    if (node.right != null) {
