import java.util.Arrays;

public class Solution {
    private static final int MOD = 1000000007;

    public int numWays(String[] words, String target) {
        int m = target.length();
        int n = words.length;
        long[][] dp = new long[m + 1][n + 1];
        dp[0][0] = 1;

        int[][] used = new int[n][];
        for (int i = 0; i < n; i++) {
            used[i] = new int[words[i].length()];
        }

        for (int i = 1; i <= m; i++) {
            for (int j = 1; j <= n; j++) {
                dp[i][j] = dp[i][j - 1];
                for (int k = 0; k < words[j - 1].length(); k++) {
                    if (target.charAt(i - 1) == words[j - 1].charAt(k) && used[j - 1][k] == 0) {
                        boolean valid = true;
                        for (int l = 0; l <= k; l++) {
                            if (used[j - 1][l] == 1) {
                                valid = false;
                                break;
                            }
                        }

                        if (valid) {
                            for (int l = 0; l <= k; l++) {
                                used[j - 1][l] = 1;
                            }
                            dp[i][j] = (dp[i][j] + dp[i - 1][j - 1]) % MOD;

                        }
                    }
                }

                // Reset used array for the next string

            }

            // Reset used array for the next character in target
            for(int i = 0; i < n; i++){
                Arrays.fill(used[i], 0);
            }
        }

        long result = 0;
        for (int j = 1; j <= n; j++) {
            result = (result + dp[m][j]) % MOD;
        }

        return (int) result;
    }
}

