import java.util.HashMap;
import java.util.Map;

public class Solution {
    public boolean closeStrings(String word1, String word2) {
        if (word1.length() != word2.length()) {
            return false;
        }

        Map<Character, Integer> freq1 = new HashMap<>();
        Map<Character, Integer> freq2 = new HashMap<>();

        for (char c : word1.toCharArray()) {
            freq1.put(c, freq1.getOrDefault(c, 0) + 1);
        }

        for (char c : word2.toCharArray()) {
            freq2.put(c, freq2.getOrDefault(c, 0) + 1);
        }

        if (freq1.size() != freq2.size()) {
            return false;
        }

        Map<Character, Character> mapping = new HashMap<>();
        for (int i = 0; i < word1.length(); i++) {
            char c1 = word1.charAt(i);
            char c2 = word2.charAt(i);

            if (!mapping.containsKey(c1)) {
                if (mapping.values().contains(c2)) {
                    return false;
                }
                mapping.put(c1, c2);
            } else {
                if (!mapping.get(c1).equals(c2)) {
                    return false;
                }
            }
        }

        Map<Character, Character> reverseMapping = new HashMap<>();
        for (Map.Entry<Character, Character> entry : mapping.entrySet()) {
            char key = entry.getKey();
            char value = entry.getValue();
            if (reverseMapping.containsKey(value)) {
                if (!reverseMapping.get(value).equals(key)) {
                    return false;
                }
            } else {
                reverseMapping.put(value, key);
            }
        }

        return true;
    }
}

