public class Solution {
    public int waysToMakeFair(int[] nums) {
        int n = nums.length;
        int count = 0;
        for (int i = 0; i < n; i++) {
            int[] temp = new int[n - 1];
            int k = 0;
            for (int j = 0; j < n; j++) {
                if (i != j) {
                    temp[k++] = nums[j];
                }
            }
            int evenSum = 0;
            int oddSum = 0;
            for (int j = 0; j < n - 1; j++) {
                if (j % 2 == 0) {
                    evenSum += temp[j];
                } else {
                    oddSum += temp[j];
                }
            }
            if (evenSum == oddSum) {
                count++;
            }
        }
        return count;
    }
}

