import java.util.Arrays;

public class Solution {
    /**
     * Given an integer array nums sorted in non-decreasing order. Build and return an integer array result with the same length as nums such that result[i] is equal to the summation of absolute differences between nums[i] and all the other elements in the array.
     * In other words, result[i] is equal to sum(|nums[i]-nums[j]|) where 0 <= j < nums.length and j != i (0-indexed).
     *
     * @param nums The input integer array.
     * @return The integer array containing the summation of absolute differences for each element.
     */
    public int[] getSumAbsoluteDifferences(int[] nums) {
        int n = nums.length;
        int[] result = new int[n];

        for (int i = 0; i < n; i++) {
            long sum = 0;
            for (int j = 0; j < n; j++) {
                sum += Math.abs((long)nums[i] - (long)nums[j]);
            }
            result[i] = (int)sum;
        }

        return result;
    }
}

