import java.util.Arrays;

public class Solution {
    /**
     * Determines the result of the game between Alice and Bob.
     *
     * @param aliceValues An array of integers representing Alice's values for each stone.
     * @param bobValues   An array of integers representing Bob's values for each stone.
     * @return 1 if Alice wins, -1 if Bob wins, and 0 if the game results in a draw.
     */
    public int stoneGameVI(int[] aliceValues, int[] bobValues) {
        int n = aliceValues.length;
        int[][] dp = new int[n + 1][2];

        for (int i = 1; i <= n; i++) {
            int diff = aliceValues[i - 1] - bobValues[i - 1];
            dp[i][0] = Math.max(dp[i - 1][0], dp[i - 1][1] + diff);
            dp[i][1] = Math.max(dp[i - 1][1], dp[i - 1][0] - diff);
        }

        if (dp[n][0] > dp[n][1]) {
            return 1;
        } else if (dp[n][0] < dp[n][1]) {
            return -1;
        } else {
            return 0;
        }
    }
}

