public class Solution {
    public int minimumOneBitOperations(int n) {
        if (n == 0) {
            return 0;
        }

        int ans = 0;
        int prev = 0;
        while (n > 0) {
            if ((n & 1) == 1) {
                if (prev == 1) {
                    ans += 1;
                } else {
                    ans += 2;
                }
            }
            prev = n & 1;
            n >>= 1;
        }
        return ans;
    }
}

