            dp[i] = dp[i - 1] + 1; // Delete the current character

            for (int j = 0; j < i; j++) {
                if (s.charAt(j) == 'b' && s.charAt(i - 1) == 'a') {

                    boolean balancedSubstr = true;
                    for(int k = j + 1; k < i - 1; k++){
                        if(s.charAt(k) == 'b'){
                            balancedSubstr = false;
                            break;
                        }
                    }

                    if(balancedSubstr){
                        dp[i] = Math.min(dp[i], dp[j]);
                    }
                }
            }

            if (s.charAt(i - 1) == 'b') {
                dp[i] = Math.min(dp[i], dp[i - 1] + 1);
            } else {
                dp[i] = Math.min(dp[i], dp[i - 1]);
            }
        }

        return dp[n];
    }
}

