import java.util.Arrays;
import java.util.PriorityQueue;

public class Solution {
    public int maxProfit(int[] inventory, int orders) {
        Arrays.sort(inventory);
        long profit = 0;
        int n = inventory.length;
        PriorityQueue<Integer> pq = new PriorityQueue<>((a, b) -> b - a);
        for (int val : inventory) {
            pq.offer(val);
        }

        while (orders > 0) {
            int top = pq.poll();
            int nextTop = pq.isEmpty() ? 0 : pq.peek();
            int diff = top - nextTop;
            int sellCount = Math.min(orders, diff);

            if (sellCount > 0) {
                long currentProfit = (long) sellCount * (top + top - sellCount + 1) / 2;
                profit = (profit + currentProfit) % 1000000007;
                orders -= sellCount;
                if (orders > 0) {
                    pq.offer(top - sellCount);
                }
            } else {
                if (!pq.isEmpty()) {
                    int currentTop = pq.peek();
                    long currentProfit = (long) orders * currentTop;
                    profit = (profit + currentProfit) % 1000000007;
                    orders = 0;
                }
            }
        }
        return (int) profit;
    }
}

