            return Integer.compare(dim1, dim2);
        });

        int[] dp = new int[n];
        for (int i = 0; i < n; i++) {
            dp[i] = arr[i][2]; // Initialize with the height of the current cuboid
            for (int j = 0; j < i; j++) {
                if (canPlace(arr[i], arr[j])) {
                    dp[i] = Math.max(dp[i], dp[j] + arr[i][2]);
                }
            }
        }

        int maxHeight = 0;
        for (int height : dp) {
            maxHeight = Math.max(maxHeight, height);
        }

        return maxHeight;
    }

    private boolean canPlace(int[] top, int[] bottom) {
        int[] dimensions = {0, 1, 2};
        for (int i = 0; i < 6; i++) {
            int[] rotatedTop = new int[3];
            if (i == 0) {
                rotatedTop[0] = top[0];
                rotatedTop[1] = top[1];
                rotatedTop[2] = top[2];
            } else if (i == 1) {
                rotatedTop[0] = top[0];
                rotatedTop[1] = top[2];
                rotatedTop[2] = top[1];
            } else if (i == 2) {
                rotatedTop[0] = top[1];
                rotatedTop[1] = top[0];
                rotatedTop[2] = top[2];
            } else if (i == 3) {
                rotatedTop[0] = top[1];
                rotatedTop[1] = top[2];
                rotatedTop[2] = top[0];
            } else if (i == 4) {
                rotatedTop[0] = top[2];
                rotatedTop[1] = top[0];
