import java.util.Arrays;

class Solution {
    /**
     * Given two lists, scores and ages, where each scores[i] and ages[i] represents the score and age of the ith player, respectively,
     * return the highest overall score of all possible basketball teams.
     * A conflict exists if a younger player has a strictly higher score than an older player.
     * A conflict does not occur between players of the same age.
     *
     * @param scores The scores of the players.
     * @param ages   The ages of the players.
     * @return The highest overall score of all possible basketball teams.
     */
    public int bestTeamScore(int[] scores, int[] ages) {
        int n = scores.length;
        int maxScore = 0;

        for (int i = 0; i < (1 << n); i++) {
            int currentScore = 0;
            int[] teamScores = new int[n];
            int[] teamAges = new int[n];
            int teamSize = 0;

            for (int j = 0; j < n; j++) {
                if ((i >> j) % 2 == 1) {
                    teamScores[teamSize] = scores[j];
                    teamAges[teamSize] = ages[j];
                    currentScore += scores[j];
                    teamSize++;
                }
            }

            boolean conflict = false;
            for (int j = 0; j < teamSize; j++) {
                for (int k = j + 1; k < teamSize; k++) {
                    if (teamAges[j] > teamAges[k] && teamScores[j] < teamScores[k]) {
                        conflict = true;
                        break;
                    }
                }
                if (conflict) {
                    break;
                }
            }

            if (!conflict) {
                maxScore = Math.max(maxScore, currentScore);
            }
        }

        return maxScore;
    }
}

