    public int[] fallingSquares(int[][] positions) {
        int n = positions.length;
        int[] ans = new int[n];

        for (int i = 0; i < n; i++) {
            int left1 = positions[i][0];
            int sideLength1 = positions[i][1];
            int right1 = left1 + sideLength1;
            int maxHeight = sideLength1;

            for (int j = 0; j < i; j++) {
                int left2 = positions[j][0];
                int sideLength2 = positions[j][1];
                int right2 = left2 + sideLength2;

                if (left1 < right2 && left2 < right1) {
                    maxHeight = Math.max(maxHeight, ans[j] + sideLength1);
                }
            }

            ans[i] = maxHeight;
        }

        return ans;
    }
}

