import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class Solution {
    public String solveEquation(String equation) {
        String[] parts = equation.split("=");
        String left = parts[0];
        String right = parts[1];

        int[] leftCoeff = parseSide(left);
        int[] rightCoeff = parseSide(right);

        int xCoeff = leftCoeff[0] - rightCoeff[0];
        int constant = leftCoeff[1] - rightCoeff[1];

        if (xCoeff == 0) {
            if (constant == 0) {
                return "Infinite solutions";
            } else {
                return "No solution";
            }
        } else {
            if (constant % xCoeff == 0) {
                int xValue = constant / xCoeff;
                return "x=" + xValue;
            } else {
                return "No solution";
            }
        }
    }

    private int[] parseSide(String side) {
        int xCoeff = 0;
        int constant = 0;

        Pattern pattern = Pattern.compile("([-+]?\\d*x)|([-+]?\\d+)");
        Matcher matcher = pattern.matcher(side);

        while (matcher.find()) {
            String term = matcher.group();
            if (term.contains("x")) {
                int coeff = 1;
                if (!term.substring(0, term.indexOf("x")).isEmpty()) {
                    coeff = Integer.parseInt(term.substring(0, term.indexOf("x")));
                }

                if (term.startsWith("+")) {
                    xCoeff += coeff;
                } else if (term.startsWith("-")) {
                    xCoeff -= coeff;
                } else {
                    xCoeff += coeff;
                }
            } else {
                if (term.equals("+") || term.equals("-")) {
                    continue;
                }
                if (term.matches("[+-]")) {
                    continue;
                }
                int num = Integer.parseInt(term);
                if (term.startsWith("+")) {
                    constant += num;
                } else if (term.startsWith("-")) {
                    constant -= num;
                } else {
                    constant += num;
                }
            }
        }

        return new int[]{xCoeff, constant};
    }
}

