import java.util.Arrays;

public class Solution {
    public int[] findRedundantDirectedConnection(int[][] edges) {
        int n = edges.length;
        int[] parent = new int[n + 1];
        Arrays.fill(parent, 0);
        int[] candidate1 = null;
        int[] candidate2 = null;
        int[] inDegree = new int[n + 1];

        for (int[] edge : edges) {
            int u = edge[0];
            int v = edge[1];
            if (parent[v] == 0) {
                parent[v] = u;
            } else {
                candidate1 = new int[]{parent[v], v};
                candidate2 = edge;
            }
            inDegree[v]++;
        }

        if (candidate1 == null) {
            return candidate2;
        }

        if (hasCycle(edges, candidate1)) {
            return candidate2;
        } else {
            return candidate1;
        }
    }

    private boolean hasCycle(int[][] edges, int[] removedEdge) {
        int n = edges.length;
        int[] inDegree = new int[n + 1];
        for (int[] edge : edges) {
            if (edge[0] != removedEdge[0] || edge[1] != removedEdge[1]) {
                inDegree[edge[1]]++;
            }
        }

        int roots = 0;
        for (int i = 1; i <= n; i++) {
            if (inDegree[i] == 0) {
                roots++;
            }
        }

        return roots > 1;
    }
}

