import java.util.HashMap;
import java.util.Map;
import java.util.PriorityQueue;

public class Solution {
    public int leastInterval(char[] tasks, int n) {
        if (tasks == null || tasks.length == 0) {
            return 0;
        }

        Map<Character, Integer> taskCounts = new HashMap<>();
        for (char task : tasks) {
            taskCounts.put(task, taskCounts.getOrDefault(task, 0) + 1);
        }

        PriorityQueue<Integer> pq = new PriorityQueue<>((a, b) -> b - a);
        for (int count : taskCounts.values()) {
            pq.offer(count);
        }

        Map<Character, Integer> lastExecutionTime = new HashMap<>();
        int time = 0;

        while (!pq.isEmpty()) {
            int maxCount = pq.poll();
            char task = ' ';
            for (Map.Entry<Character, Integer> entry : taskCounts.entrySet()) {
                if (taskCounts.get(entry.getKey()) == maxCount) {
                    task = entry.getKey();
                    break;
                }
            }

            if (lastExecutionTime.containsKey(task) && time - lastExecutionTime.get(task) <= n) {
                time += (n - (time - lastExecutionTime.get(task)));
            }

            taskCounts.put(task, maxCount - 1);
            lastExecutionTime.put(task, time);

            if (taskCounts.get(task) > 0) {
                pq.offer(taskCounts.get(task));
            }
        }

        return time;
    }
}

