        Queue<Character> queue = new LinkedList<>();
        for (char c : senate.toCharArray()) {
            queue.offer(c);
        }

        while (queue.size() > 1) {
            char first = queue.poll();
            char second = queue.poll();

            if (first == second) {
                queue.offer(first);
            } else if (first == 'R' && second == 'D') {
                queue.offer('R');
            } else {
                queue.offer('D');
            }
        }

