public class Solution {
    public List<Double> averageOfLevels(TreeNode root) {
        List<Double> averages = new ArrayList<>();
        if (root == null) {
            return averages;
        }

        List<List<Double>> levelValues = new ArrayList<>();
        dfs(root, 0, levelValues);

        for (List<Double> values : levelValues) {
            double sum = 0;
            for (double value : values) {
                sum += value;
            }
            averages.add(sum / values.size());
        }

        return averages;
    }

    private void dfs(TreeNode node, int level, List<List<Double>> levelValues) {
        if (node == null) {
            return;
        }

        if (levelValues.size() <= level) {
            levelValues.add(new ArrayList<>());
        }

