import java.util.List;
import java.util.PriorityQueue;

public class Solution {
    /**
     * You have k lists of sorted integers in non-decreasing order. Find the smallest range that includes at least one number from each of the k lists.
     * We define the range [a, b] is smaller than range [c, d] if b - a < d - c or a < c if b - a == d - c.
     *
     * @param lists The k lists of sorted integers.
     * @return The smallest range that includes at least one number from each of the k lists.
     */
    public int[] smallestRange(List<List<Integer>> lists) {
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[0] - b[0]);
        int max = Integer.MIN_VALUE;
        for (int i = 0; i < lists.size(); i++) {
            pq.offer(new int[]{lists.get(i).get(0), i, 0});
            max = Math.max(max, lists.get(i).get(0));
        }
        int range = Integer.MAX_VALUE;
        int start = -1, end = -1;
        while (pq.size() == lists.size()) {
            int[] curr = pq.poll();
            int min = curr[0];
            int listIndex = curr[1];
            int elementIndex = curr[2];
            if (max - min < range) {
                range = max - min;
                start = min;
                end = max;
            } else if (max - min == range && min < start) {
                start = min;
                end = max;
            }
            if (elementIndex + 1 < lists.get(listIndex).size()) {
                int nextElement = lists.get(listIndex).get(elementIndex + 1);
                pq.offer(new int[]{nextElement, listIndex, elementIndex + 1});
                max = Math.max(max, nextElement);
            }
        }

        if (start > end) {
            int temp = start;
            start = end;
            end = temp;
        }

        return new int[]{start, end};
    }
}

