import java.util.List;
import java.util.ArrayList;
import java.util.Arrays;

public class Solution {
    public int shoppingOffers(int[] price, int[] needs, List<List<Integer>> special) {
        int n = price.length;
        int[] baseCost = new int[n];
        for (int i = 0; i < n; i++) {
            baseCost[i] = price[i] * needs[i];
        }
        int totalBaseCost = Arrays.stream(baseCost).sum();

        int minCost = totalBaseCost;

        for (List<Integer> offer : special) {
            int offerPrice = offer.get(n);
            int[] newNeeds = new int[n];
            boolean validOffer = true;
            for (int i = 0; i < n; i++) {
                newNeeds[i] = needs[i] - offer.get(i);
                if (newNeeds[i] < 0) {
                    validOffer = false;
                    break;
                }
            }

            if (validOffer) {
                int offerCost = offerPrice + shoppingOffers(price, newNeeds, special);
                minCost = Math.min(minCost, offerCost);
            }
        }

        return minCost;
    }
}

