        res.get(row).set(col, String.valueOf(node.val));

        if (level < height) {
            int leftCol = col - (int) Math.pow(2, height - level - 1);
            int rightCol = col + (int) Math.pow(2, height - level - 1);

            dfs(node.left, res, row + 1, leftCol, level + 1, height);
            dfs(node.right, res, row + 1, rightCol, level + 1, height);
        }
    }
