public class Solution {
    public int[] constructArray(int n, int k) {
        int[] result = new int[n];
        int left = 1;
        int right = n;
        int index = 0;

        if (k == 0) {
            for (int i = 1; i <= n; i++) {
                result[i - 1] = i;
            }
            return result;
        }

        if (k == n - 1) {
            for (int i = n; i >= 1; i--) {
                result[i - 1] = i;
            }
            return result;
        }

        while (left <= right) {
            result[index++] = left++;
            if (index == n) break;
            result[index++] = right--;
        }

        if (index < n) {
            for (int i = index; i < n; i++) {
                result[i] = left++;
            }
        }

        return result;
    }
