// #Hard #String #Dynamic_Programming #2022_06_23_Time_2_ms_(100.00%)_Space_40.2_MB_(99.14%)
public class Solution {
    public int numDistinct(String s, String t) {
        int n = s.length();
        int m = t.length();

        // dp[i][j] represents the number of distinct subsequences of s[0...i-1] which equals t[0...j-1]
        int[][] dp = new int[n + 1][m + 1];

        // If t is empty, there is always 1 way to form an empty string from s (by deleting all characters)
        for (int i = 0; i <= n; i++) {
            dp[i][0] = 1;
        }

        // If s is empty and t is not, there are 0 ways to form t from s
        for (int j = 1; j <= m; j++) {
            dp[0][j] = 0;
        }

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                if (s.charAt(i - 1) == t.charAt(j - 1)) {
                    // If the characters match, we have two options:
                    // 1. Include the character in the subsequence (dp[i-1][j-1])
                    // 2. Exclude the character from the subsequence (dp[i-1][j])
                    dp[i][j] = dp[i - 1][j - 1] + dp[i - 1][j];
                } else {
                    // If the characters don't match, we can only exclude the character from s
                    dp[i][j] = dp[i - 1][j];
                }
            }
        }

        return dp[n][m];
    }
}

