    public TreeNode sortedListToBST(ListNode head) {
        // Empty list -> empty tree / sub-tree
        if (head == null) {
            return null;
        }

        // Find the length of the list
        int len = 0;
        ListNode curr = head;
        while (curr != null) {
            len++;
            curr = curr.next;
        }

        return sortedListToBSTHelper(head, 0, len - 1);
    }

    private TreeNode sortedListToBSTHelper(ListNode head, int start, int end) {
        if (start > end) {
            return null;
        }

        int mid = start + (end - start) / 2;

        ListNode slow = head;
        for (int i = 0; i < mid; i++) {
            slow = slow.next;
        }

        TreeNode root = new TreeNode(slow.val);

        root.left = sortedListToBSTHelper(head, start, mid - 1);
        root.right = sortedListToBSTHelper(slow.next, mid + 1, end);

        return root;
    }
}

