        int n = text.length();
        int maxLen = 0;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int len = 0;
                while (i + len < n && j + len < n && text.charAt(i + len) == text.charAt(j + len)) {
                    len++;
                }
                maxLen = Math.max(maxLen, len);
            }
        }

        return maxLen;
    }
}

