            maxLeft = Math.max(maxLeft, left[i]);
        }

        right[n - 1] = arr[n - 1];
        int maxRight = arr[n - 1];
        for (int i = n - 2; i >= 0; i--) {
            right[i] = Math.max(arr[i], right[i + 1] + arr[i]);
