    public boolean btreeGameWinningMove(TreeNode root, int n, int x) {
        if (n == 1) {
            return false;
        }

        for (int y = 1; y <= n; y++) {
            if (y != x) {
                if (canWin(root, n, x, y)) {
                    return true;
                }
            }
        }

        return false;
    }

    private boolean canWin(TreeNode root, int n, int x, int y) {
        TreeNode rootX = findNode(root, x);
        TreeNode rootY = findNode(root, y);

        if (rootX == null || rootY == null) {
            return false;
        }

        int scorePlayer1 = 0;
        int scorePlayer2 = 0;

        List<TreeNode> player1Nodes = new ArrayList<>();
        List<TreeNode> player2Nodes = new ArrayList<>();

        player1Nodes.add(rootX);
        player2Nodes.add(rootY);

        boolean player1Turn = true;

        while (true) {
            if (player1Turn) {
                TreeNode nextNode = findNextNode(player1Nodes, root, player2Nodes);
                if (nextNode == null) {
                    break;
                }
                player1Nodes.add(nextNode);
                scorePlayer1++;
            } else {
                TreeNode nextNode = findNextNode(player2Nodes, root, player1Nodes);
                if (nextNode == null) {
                    break;
                }
                player2Nodes.add(nextNode);
                scorePlayer2++;
            }
            player1Turn = !player1Turn;
        }

        return scorePlayer1 < scorePlayer2;
    }

    private TreeNode findNextNode(List<TreeNode> coloredNodes, TreeNode root, List<TreeNode> opponentColoredNodes) {
        for (TreeNode node : coloredNodes) {
            if (node.left != null && !isColored(node.left, opponentColoredNodes)) {
                return node.left;
            }
            if (node.right != null && !isColored(node.right, opponentColoredNodes)) {
                return node.right;
            }

            TreeNode parent = findParent(root, node);
            if (parent != null && !isColored(parent, opponentColoredNodes)) {
                return parent;
            }
        }
        return null;
    }

    private boolean isColored(TreeNode node, List<TreeNode> coloredNodes) {
        if (node == null) {
            return false;
        }
        return coloredNodes.contains(node);
    }

    private TreeNode findParent(TreeNode root, TreeNode node) {
        if (root == null || root == node) {
            return null;
        }

        if ((root.left == node) || (root.right == node)) {
            return root;
        }

        TreeNode left = findParent(root.left, node);
        if (left != null) {
            return left;
        }

        return findParent(root.right, node);
    }

    private TreeNode findNode(TreeNode root, int value) {
        if (root == null) {
            return null;
        }

        if (root.val == value) {
            return root;
        }

        TreeNode left = findNode(root.left, value);
        if (left != null) {
            return left;
        }

        return findNode(root.right, value);
    }
}

