import java.util.Stack;

public class Solution {
    public boolean parseBoolExpr(String expression) {
        if (expression == null || expression.isEmpty()) {
            return false;
        }

        Stack<Boolean> stack = new Stack<>();
        char currentOperator = ' ';

        for (char c : expression.toCharArray()) {
            if (c == 't') {
                stack.push(true);
            } else if (c == 'f') {
                stack.push(false);
            } else if (c == '!') {
                if (stack.isEmpty()) {
                    return false; // Handle invalid expression
                }
                Boolean top = stack.pop();
                stack.push(!top);
            } else if (c == '&') {
                currentOperator = '&';
            } else if (c == '|') {
                currentOperator = '|';
            } else if (c == ')') {
                List<Boolean> operands = new ArrayList<>();
                while (!stack.isEmpty()) {
                    operands.add(0, stack.pop());
                }

                boolean result = true;
                if (currentOperator == '&') {
                    if (operands.isEmpty()) {
                        return false; // Handle invalid expression
                    }
                    result = true;
                    for (boolean operand : operands) {
                        result &= operand;
                    }
                } else if (currentOperator == '|') {
                    if (operands.isEmpty()) {
                        return false; // Handle invalid expression
                    }
                    result = false;
                    for (boolean operand : operands) {
                        result |= operand;
                    }
                }
                stack.push(result);
                currentOperator = ' ';
            }
        }

        if (stack.isEmpty()) {
            return false; // Handle invalid expression
        }
        return stack.pop();
    }
}

