        if (node.left == null && node.right == null) {
            if (d > depth[0]) {
                depth[0] = d;
                result[0] = node;
            }
            return node;
        }

        TreeNode left = dfs(node.left, d + 1, depth, result);
        TreeNode right = dfs(node.right, d + 1, depth, result);

        if (left != null && right != null) {
            return node;
        } else if (left != null) {
            return left;
        } else {
            return right;
        }
    }
}

