public class Solution {
    private static final long MOD = 1000000007;

    public int kConcatenationMaxSum(int[] arr, int k) {
        long maxSoFar = kadane(arr);
        long arrSum = 0;
        for (int num : arr) {
            arrSum += num;
        }

        if (k == 1) {
            return (int) (maxSoFar % MOD);
        }

        long maxTwo = kadane(concatenate(arr, 2));

        if (arrSum > 0) {
            return (int) ((maxTwo + (long) (k - 2) * arrSum) % MOD);
        } else {
            return (int) (maxTwo % MOD);
        }
    }

    private long kadane(int[] arr) {
        long maxSoFar = Long.MIN_VALUE;
        long currentMax = 0;
        for (int num : arr) {
            currentMax += num;
            if (currentMax < 0) {
                currentMax = 0;
            }
            maxSoFar = Math.max(maxSoFar, currentMax);
        }
        if (maxSoFar == Long.MIN_VALUE) {
            maxSoFar = Arrays.stream(arr).max().orElse(0);
        }
        return maxSoFar;
    }

    private int[] concatenate(int[] arr, int k) {
        int[] result = new int[arr.length * k];
        for (int i = 0; i < k; i++) {
            System.arraycopy(arr, 0, result, i * arr.length, arr.length);
        }
        return result;
    }
}

