import java.util.Stack;

public class Solution {
    public String reverseParentheses(String s) {
        Stack<Integer> stack = new Stack<>();
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) == '(') {
                stack.push(i);
            } else if (s.charAt(i) == ')') {
                int start = stack.pop();
                int end = i;
                String sub = s.substring(start + 1, end);
                StringBuilder reversed = new StringBuilder(sub).reverse();
                s = s.substring(0, start) + reversed.toString() + s.substring(end + 1);
                i = start + reversed.length() - 1;
            }
        }
        return s;
    }
}

