import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
public class Solution {
    public List<Integer> findNumOfValidWords(String[] words, String[] puzzles) {
        List<Integer> result = new ArrayList<>();
        for (String puzzle : puzzles) {
            int count = 0;
            for (String word : words) {
                if (isValid(word, puzzle)) {
                    count++;
                }
            }
            result.add(count);
        }
        return result;
    }

    private boolean isValid(String word, String puzzle) {
        if (word == null || puzzle == null) {
            return false;
        }

        if (word.length() == 0 && puzzle.length() > 0) {
            return false;
        }

        if (word.length() == 0 && puzzle.length() == 0) {
            return true;
        }

        if (puzzle.length() == 0 && word.length() > 0) {
            return false;
        }

        if (word.indexOf(puzzle.charAt(0)) == -1) {
            return false;
        }

        HashMap<Character, Integer> puzzleMap = new HashMap<>();
        for (char c : puzzle.toCharArray()) {
            puzzleMap.put(c, puzzleMap.getOrDefault(c, 0) + 1);
        }

        HashMap<Character, Integer> wordMap = new HashMap<>();
        for (char c : word.toCharArray()) {
            wordMap.put(c, wordMap.getOrDefault(c, 0) + 1);
        }

        for (char c : wordMap.keySet()) {
            if (!puzzleMap.containsKey(c)) {
                return false;
            }
        }

        return true;
    }
}

