import java.util.HashMap;
import java.util.Map;

public class Solution {
    public String alphabetBoardPath(String target) {
        Map<Character, int[]> charMap = new HashMap<>();
        for (int i = 0; i < 6; i++) {
            for (int j = 0; j < 5; j++) {
                if (i == 5 && j == 5) {
                    charMap.put('z', new int[]{5, 5});
                } else {
                    charMap.put((char) ('a' + i * 5 + j), new int[]{i, j});
                }
            }
        }

        StringBuilder path = new StringBuilder();
        int row = 0;
        int col = 0;

        for (char c : target.toCharArray()) {
            int[] targetPos = charMap.get(c);
            int targetRow = targetPos[0];
            int targetCol = targetPos[1];

            // Move vertically first
            if (targetRow > row) {
                for (int i = 0; i < targetRow - row; i++) {
                    path.append('D');
                }
            } else if (targetRow < row) {
                for (int i = 0; i < row - targetRow; i++) {
                    path.append('U');
                }
            }

            // Move horizontally
            if (targetCol > col) {
                for (int i = 0; i < targetCol - col; i++) {
                    path.append('R');
                }
            } else if (targetCol < col) {
                for (int i = 0; i < col - targetCol; i++) {
                    path.append('L');
                }
            }

            path.append('!');
            row = targetRow;
            col = targetCol;
        }

        return path.toString();
    }
}

