import java.util.Arrays;

public class Solution {
    public int[] numSmallerByFrequency(String[] words, String[] queries) {
        int[] answer = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            int count = 0;
            int queryFrequency = getFrequency(queries[i]);
            for (String word : words) {
                int wordFrequency = getFrequency(word);
                if (queryFrequency < wordFrequency) {
                    count++;
                }
            }
            answer[i] = count;
        }
        return answer;
    }

    private int getFrequency(String s) {
        int[] charCounts = new int[26];
        for (char c : s.toCharArray()) {
            charCounts[c - 'a']++;
        }

        int minCharIndex = 0;
        for (int i = 1; i < 26; i++) {
            if (charCounts[i] > 0 && charCounts[i] < charCounts[minCharIndex]) {
                minCharIndex = i;
            } else if (charCounts[i] > 0 && charCounts[minCharIndex] == 0) {
                minCharIndex = i;
            }
        }

        if (charCounts[minCharIndex] == 0) {
            for (int i = 0; i < 26; i++) {
                if (charCounts[i] > 0) {
                    minCharIndex = i;
                    break;
                }
            }
        }

        return charCounts[minCharIndex];
    }
}

