import java.util.Arrays;

public class Solution {
    public int[] recoverArray(int n, int[] sums) {
        int[] ans = new int[n];
        Arrays.sort(sums);

        if (n == 1) {
            ans[0] = sums[0];
            return ans;
        }

        long totalSum = 0;
        for (int sum : sums) {
            totalSum += sum;
        }

        ans[0] = (int) ((totalSum - sums[0]) / (1 << (n - 1)));

        for (int i = 1; i < n; i++) {
            ans[i] = sums[i] - sums[i - 1] - ans[0];
        }

        return ans;
    }
}

