import java.util.Random;

public class Solution {
    public int[] rearrangeArray(int[] nums) {
        if (nums == null || nums.length <= 2) {
            return nums;
        }

        Random random = new Random();
        int n = nums.length;
        int[] rearranged = new int[n];

        for (int i = 0; i < n; i++) {
            int randomIndex = random.nextInt(n);
            rearranged[i] = nums[randomIndex];
        }

        boolean valid = false;
        int attempts = 0;
        while (!valid && attempts < 1000) {
            valid = true;
            for (int i = 1; i < n - 1; i++) {
                if ((rearranged[i - 1] + rearranged[i + 1]) / 2 == rearranged[i]) {
                    valid = false;
                    break;
                }
            }

            if (!valid) {
                // Reshuffle the array
                for (int i = 0; i < n; i++) {
                    int randomIndex = random.nextInt(n);
                    int temp = rearranged[i];
                    rearranged[i] = rearranged[randomIndex];
                    rearranged[randomIndex] = temp;
                }
                attempts++;
            }
        }

        if (!valid) {
            // If after many attempts, a valid arrangement is not found,
            // return the original array. This is a fallback to ensure
            // the function always returns a result.
            return nums;
        }

        return rearranged;
    }
}

