// #Medium #String #Greedy #Two_Pointers #Stack #2022_05_21_Time_17_ms_(93.71%)_Space_50_MB_(91.93%)
public class Solution {
    public int minSwaps(String s) {
        int open = 0;
        int close = 0;
        int swaps = 0;
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) == '[') {
                open++;
            } else {
                close++;
            }
            if (close > open) {
                swaps++;
                open++;
                close--;
            }
        }
        return swaps;
    }
}

