import java.util.Arrays;
import java.util.Comparator;

public class Solution {
    public int eliminateMaximum(int[] dist, int[] speed) {
        int n = dist.length;
        Monster[] monsters = new Monster[n];
        for (int i = 0; i < n; i++) {
            monsters[i] = new Monster(dist[i], speed[i]);
        }
        Arrays.sort(monsters, Comparator.comparingDouble(Monster::timeToReachCity));
        int eliminated = 0;
        double currentTime = 0;
        for (Monster monster : monsters) {
            if (currentTime < monster.timeToReachCity()) {
                eliminated++;
                currentTime++;
            } else {
                break;
            }
        }
        return eliminated;
    }
    private static class Monster {
        int dist;
        int speed;
        public Monster(int dist, int speed) {
            this.dist = dist;
            this.speed = speed;
        }
        public double timeToReachCity() {
            return (double) dist / speed;
        }
    }
}

