import java.util.Arrays;

public class Solution {

    /**
     * Finds a peak element in a 2D grid.
     *
     * @param mat The 2D grid.
     * @return The row and column indices of a peak element.
     */
    public int[] findPeakGrid(int[][] mat) {
        int m = mat.length;
        int n = mat[0].length;

        int start = 0;
        int end = n - 1;

        while (start <= end) {
            int mid = start + (end - start) / 2;
            int maxRow = 0;
            for (int i = 0; i < m; i++) {
                if (mat[i][mid] > mat[maxRow][mid]) {
                    maxRow = i;
                }
            }

            boolean isPeak = true;
            if (mid > 0 && mat[maxRow][mid - 1] > mat[maxRow][mid]) {
                end = mid - 1;
                isPeak = false;
            } else if (mid < n - 1 && mat[maxRow][mid + 1] > mat[maxRow][mid]) {
                start = mid + 1;
                isPeak = false;
            }

            if (isPeak) {
                return new int[]{maxRow, mid};
            }
        }

        return null; // Should not happen given the problem constraints
    }
}
